const markCrawlTruncated = `-- name: MarkCrawlTruncated :exec
UPDATE web_crawls
SET truncated = true, truncated_reason = CASE WHEN truncated_reason = '' THEN $1::text ELSE truncated_reason END
WHERE id = $2
`

type MarkCrawlTruncatedParams struct {
	Reason string
	ID     uuid.UUID
}

// The first reason a run stopped early is kept.
func (q *Queries) MarkCrawlTruncated(ctx context.Context, arg MarkCrawlTruncatedParams) error {
	_, err := q.db.Exec(ctx, markCrawlTruncated, arg.Reason, arg.ID)
	return err
}

