// Frontiers of finished earlier runs are only diagnostic; the latest is kept.
func (q *Queries) PruneFrontiers(ctx context.Context, arg PruneFrontiersParams) error {
	_, err := q.db.Exec(ctx, pruneFrontiers, arg.SourceID, arg.KeepCrawlID)
	return err
}

