const waitingCrawls = `-- name: WaitingCrawls :many
SELECT id, source_id, team_id, status, trigger, config, pages_discovered, pages_fetched, pages_changed, pages_unchanged, pages_skipped, pages_failed, documents_deleted, truncated, error, created_by, created_at, started_at, finished_at, truncated_reason, waiting_reason, waiting_until FROM web_crawls
WHERE team_id = $1 AND status = 'queued' AND waiting_reason = 'concurrent_crawls'
ORDER BY created_at, id
LIMIT $2
`

type WaitingCrawlsParams struct {
	TeamID   uuid.NullUUID
	PageSize int32
}

// Runs waiting for a crawl slot, oldest first.
func (q *Queries) WaitingCrawls(ctx context.Context, arg WaitingCrawlsParams) ([]WebCrawl, error) {
	rows, err := q.db.Query(ctx, waitingCrawls, arg.TeamID, arg.PageSize)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []WebCrawl{}
	for rows.Next() {
		var i WebCrawl
		if err := rows.Scan(
			&i.ID,
			&i.SourceID,
			&i.TeamID,
			&i.Status,
			&i.Trigger,
			&i.Config,
			&i.PagesDiscovered,
			&i.PagesFetched,
			&i.PagesChanged,
			&i.PagesUnchanged,
			&i.PagesSkipped,
			&i.PagesFailed,
			&i.DocumentsDeleted,
			&i.Truncated,
			&i.Error,
			&i.CreatedBy,
			&i.CreatedAt,
			&i.StartedAt,
			&i.FinishedAt,
			&i.TruncatedReason,
			&i.WaitingReason,
			&i.WaitingUntil,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}
